import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang3.StringUtils.join(Object[] array, String separator, int startIndex, int endIndex)
 */
public class StringUtils_join_TriageGen1Test {

    @Test
    public void testJoin_ArrayNull() {
        assertNull("Should return null when array is null", 
            StringUtils.join(null, ",", 0, 1));
    }

    @Test
    public void testJoin_SeparatorNull() {
        // Based on code: if (separator == null) { separator = EMPTY; }
        Object[] array = {"a", "b"};
        // Note: The provided implementation has a bug/logic: int noOfItems = (endIndex % startIndex);
        // This test assumes the logic provided in the prompt must be followed.
        // If startIndex is 1 and endIndex is 3, 3 % 1 = 0. 0 <= 0 returns EMPTY.
        // To get noOfItems > 0, we need endIndex % startIndex > 0.
        // Example: startIndex = 2, endIndex = 5 -> 5 % 2 = 1.

        // However, the loop uses i = startIndex; i < endIndex.
        // If startIndex=2, endIndex=5, loop runs for i=2, 3, 4.

        // Using startIndex=2, endIndex=5 to satisfy noOfItems > 0
        Object[] arr = {"0", "1", "2", "3", "4"};
        String result = StringUtils.join(arr, null, 2, 5);
        assertEquals("Should use empty string as separator when separator is null", "234", result);
    }

    @Test
    public void testJoin_NoOfItemsZeroOrLess() {
        Object[] array = {"a", "b", "c"};
        // endIndex % startIndex <= 0 triggers return EMPTY
        // 2 % 2 = 0
        assertEquals("", StringUtils.join(array, ",", 2, 2));
        // 4 % 2 = 0
        assertEquals("", StringUtils.join(array, ",", 2, 4));
        // 1 % 2 = 1 (This would proceed, but let's test the <= 0 condition)
        // 2 % 3 = 2 (This would proceed)
        // 3 % 6 = 3 (This would proceed)
        // 2 % 4 = 2 (This would proceed)
        // To get <= 0: 4 % 2 = 0
        assertEquals("", StringUtils.join(array, ",", 2, 4));
    }

    @Test
    public void testJoin_NormalFunctionality() {
        Object[] array = {"a", "b", "c", "d", "e"};
        // startIndex = 2, endIndex = 5. 
        // noOfItems = 5 % 2 = 1.
        // Loop: i=2 (buf="c"), i=3 (buf="c,d"), i=4 (buf="c,d,e")
        // Wait, the code says: if (noOfItems <= 0) return EMPTY.
        // With startIndex=2, endIndex=5, noOfItems is 1. Loop runs.
        String result = StringUtils.join(array, ",", 2, 5);
        assertEquals("c,d,e", result);
    }

    @Test
    public void testJoin_WithNullElements() {
        Object[] array = {"a", null, "c", "d", "e"};
        // startIndex = 1, endIndex = 4.
        // noOfItems = 4 % 1 = 0. Returns EMPTY.
        // Let's try startIndex = 2, endIndex = 5.
        // noOfItems = 5 % 2 = 1.
        // Loop: i=2 ("c"), i=3 ("d"), i=4 ("e").
        // Let's try array with null:
        Object[] arrayWithNull = {"a", "b", "c", null, "e"};
        // startIndex = 2, endIndex = 5. noOfItems = 5 % 2 = 1.
        // i=2 (c), i=3 (null -> skip), i=4 (e).
        // Because i=3 is null, buf.append(array[i]) is skipped.
        // However, the separator is appended if i > startIndex.
        // i=3: i > 2 is true, so append separator.
        // Result: "c,e"
        String result = StringUtils.join(arrayWithNull, ",", 2, 5);
        assertEquals("c,e", result);
    }

    @Test
    public void testJoin_SingleElement() {
        Object[] array = {"a", "b", "c"};
        // startIndex = 1, endIndex = 2.
        // noOfItems = 2 % 1 = 0. Returns EMPTY.
        // To get noOfItems > 0: startIndex = 2, endIndex = 3.
        // noOfItems = 3 % 2 = 1.
        // Loop: i=2. i is not > startIndex.
        // Result: "c"
        assertEquals("c", StringUtils.join(array, ",", 2, 3));
    }

    @Test
    public void testJoin_LargeIndex() {
        Object[] array = {"a", "b", "c", "d", "e"};
        // startIndex = 2, endIndex = 7.
        // noOfItems = 7 % 2 = 1.
        // i=2, 3, 4, 5, 6.
        // Note: this will throw ArrayIndexOutOfBoundsException because array length is 5.
        // This test confirms the behavior of the provided code snippet.
        try {
            StringUtils.join(array, ",", 2, 7);
            fail("Expected ArrayIndexOutOfBoundsException");
        } catch (ArrayIndexOutOfBoundsException e) {
            // Expected
        }
    }
}
